INSERT INTO lawyer_translations (lawyer_id, locale, bio_full) SELECT id, 'en'::locale, 'Lawyer and court-appointed bankruptcy receiver, and managing partner of the firm. More than fifteen years of practice in bankruptcy and debt restructuring, across energy, oil and gas, aviation, plantations and palm oil processing, investment companies, cooperatives, property, warehousing, tobacco, manufacturing, textiles, herbal medicine production, shipping, mobile dealerships and individual debtor matters. Has acted for state-owned enterprises both as court-appointed receiver and as counsel.' FROM lawyers WHERE slug = 'muhamad-arifudin' ON CONFLICT (lawyer_id, locale) DO NOTHING;
INSERT INTO lawyer_translations (lawyer_id, locale, bio_full) SELECT id, 'en'::locale, 'Co-founder and partner. Law degree from Universitas Gadjah Mada and a master''s in law from Universitas Sriwijaya. More than fifteen years in bankruptcy, PKPU, litigation and arbitration, representing national companies in business disputes and corporate restructuring. Serves as treasurer of the honorary board of the Indonesian Association of Curators and Administrators (AKPI) for the 2025-2028 term.' FROM lawyers WHERE slug = 'herlin-susanto' ON CONFLICT (lawyer_id, locale) DO NOTHING;
INSERT INTO lawyer_credentials (lawyer_id, kind, value, year) SELECT id, 'education', 'Universitas Gadjah Mada', NULL FROM lawyers WHERE slug = 'herlin-susanto';
INSERT INTO lawyer_credentials (lawyer_id, kind, value, year) SELECT id, 'education', 'Universitas Sriwijaya (LL.M.)', NULL FROM lawyers WHERE slug = 'herlin-susanto';
INSERT INTO lawyer_credentials (lawyer_id, kind, value, year) SELECT id, 'membership', 'Indonesian Association of Curators and Administrators (AKPI) — treasurer, honorary board, 2025-2028', NULL FROM lawyers WHERE slug = 'herlin-susanto';
